import SwiftUI
import AppKit

struct AIProviderBrandIcon: View {
    let provider: String
    var size: CGFloat = 20
    var isSelected: Bool = false
    
    var body: some View {
        Group {
            if let nsImage = Self.image(for: provider) {
                Image(nsImage: nsImage)
                    .resizable()
                    .aspectRatio(contentMode: .fit)
                    .frame(width: size, height: size)
            } else {
                fallbackIcon
            }
        }
    }
    
    @ViewBuilder
    private var fallbackIcon: some View {
        if provider == "github" || provider == "copilot" {
            Image(systemName: "terminal.fill")
                .font(.system(size: size * 0.75))
                .foregroundColor(.purple)
                .frame(width: size, height: size)
        } else {
            Image(systemName: "cpu")
                .font(.system(size: size * 0.7))
                .foregroundColor(.secondary)
                .frame(width: size, height: size)
        }
    }
    
    private static var iconCache: [String: NSImage] = [:]
    
    static func image(for provider: String) -> NSImage? {
        let key = provider.lowercased()
        if let cached = iconCache[key] {
            return cached
        }
        guard let base64 = base64Data[key],
              let data = Data(base64Encoded: base64),
              let img = NSImage(data: data) else {
            return nil
        }
        iconCache[key] = img
        return img
    }
    
    private static let base64Data: [String: String] = [
        "omni": "",
        "openai": "",
        "anthropic": "",
        "gemini": "",
        "deepseek": "",
        "qwen": "",
        "grok": "",
        "glm": "",
        "local": "",
    ]
}
